/** A calculator. */
export class Calculator {
    /** Add values.
     * @param {number} left - First.
     * @param {number} right - Second.
     * @returns {number} Sum.
     */
    add(left, right) {
        return left + right;
    }
}

/** The answer. */
export const answer = 42;

/** Double a number.
 * @param {number} value - Input.
 * @returns {number} Output.
 */
export const twice = value => value * 2;
